//! String-heavy API that can use &str instead.

/// Represents a label.
#[derive(Debug, Clone, PartialEq)]
pub struct Label {
    value: String,
    prefix: String,
}

impl Label {
    /// Create with owned strings — MIGRATION: parameters should be &str.
    pub fn new(value: String, prefix: String) -> Self {
        Label { value, prefix }
    }

    /// Returns formatted label.
    pub fn display(&self) -> String {
        format!("[{}] {}", self.prefix, self.value)
    }

    /// Check if label matches — MIGRATION: param should be &str.
    pub fn matches(&self, other: String) -> bool {
        self.value == other
    }

    /// Prefix the label — MIGRATION: param should be &str.
    pub fn with_prefix(&self, prefix: String) -> Label {
        Label {
            value: self.value.clone(),
            prefix,
        }
    }

    pub fn value(&self) -> &str {
        &self.value
    }
}

// TODO: impl From<&str> for Label (use empty prefix)

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_with_str() {
        // After migration, should accept &str
        let l = Label::new("foo", "TAG");
        assert_eq!(l.display(), "[TAG] foo");
    }

    #[test]
    fn test_matches_with_str() {
        let l = Label::new("hello", "X");
        assert!(l.matches("hello"));
        assert!(!l.matches("world"));
    }

    #[test]
    fn test_with_prefix_str() {
        let l = Label::new("item", "OLD");
        let l2 = l.with_prefix("NEW");
        assert_eq!(l2.display(), "[NEW] item");
    }

    #[test]
    fn test_from_str() {
        let l = Label::from("myvalue");
        assert_eq!(l.value(), "myvalue");
        assert_eq!(l.display(), "[] myvalue");
    }
}
